from typing import List
import numpy as np      # type: ignore

class FindStatistics:
    def __init__(self, name: str):
        self.name = name

    def find_average(self, list: List[int]):
        """Find the average of a list of integers"""
        print(f"The mean of {self.name} is: {np.mean(list)}")
        return np.mean(list)
    
    def find_median(self, list: List[int]):
        """Find the median of a list of integers"""
        print(f"The median of {self.name} is: {np.median(list)}")
        return np.median(list)
    
    def find_standard_deviation(self, list: List[int]):
        """Find the standard deviation of a list of integers"""
        print(f"The standard deviation of {self.name} is: {np.std(list)}")
        return np.std(list)
    
    def find_quartiles(self, list: List[int]):
        """Find the quartiles of a list of integers"""
        quartiles = np.percentile(list, [25, 50, 75])
        print(f"The quartiles (25th, 50th, 75th) of {self.name} are: {quartiles}")
        return quartiles
    
    def find_length(self, list: List[int]):
        """Find the length of a list of integers"""
        print(f"The length of {self.name} is: {len(list)}")
        return len(list)
    
